import{_ as o,o as t,c as r,a0 as n}from"./chunks/framework.Bzl7znUD.js";const g=JSON.parse('{"title":"Why no CRDT for code","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/no-crdt.md","filePath":"explanation/no-crdt.md"}'),a={name:"explanation/no-crdt.md"};function s(i,e,c,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="why-no-crdt-for-code" tabindex="-1">Why no CRDT for code <a class="header-anchor" href="#why-no-crdt-for-code" aria-label="Permalink to &quot;Why no CRDT for code&quot;">​</a></h1><p>CRDTs are right for the <em>log</em>, wrong for the <em>tree</em>.</p><p><strong>For the WAL:</strong> when replicas append ops and diverge, a CRDT-style merge (grow-only set + causal order) converges the log with no coordination — same events, same state. That part we keep.</p><p><strong>For the tree:</strong> a CRDT auto-merge produces a <em>syntactically</em> merged file, not a semantically correct one. Two agents inserting different <code>main()</code> bodies converge to a file that compiles only by luck. Code needs decisions, not convergence.</p><p>So sturn splits the difference:</p><ul><li>The <strong>log</strong> merges deterministically (CRDT semantics; a <code>libgrite-git</code> impl is on the backlog).</li><li>The <strong>tree</strong> is produced by <code>snap</code> — a deterministic reduction over ops on a base. When ops collide semantically, that&#39;s a decision for a reviewer, not a merge algorithm.</li><li><strong>Claims</strong> make most collisions never happen — prevention beats resolution.</li></ul>',6)])])}const h=o(a,[["render",s]]);export{g as __pageData,h as default};
